const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  source.folderName ||
  args.folderName ||
  args.targetName ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function extractFolderName(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'xoa folder',
    'xoa thu muc',
    'bo folder vao thung rac',
    'delete folder',
    'delete directory',
    'move folder to trash',
  ];

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      return cleanName(original.slice(prefix.length + 1));
    }

    if (normalized === prefix) {
      return '';
    }
  }

  return '';
}

const folderId =
  source.folderId ||
  source.targetId ||
  args.folderId ||
  args.targetId ||
  payload.folderId ||
  payload.targetId ||
  '';

const folderName = cleanName(
  source.folderName ||
  source.targetName ||
  args.folderName ||
  args.targetName ||
  payload.folderName ||
  payload.targetName ||
  extractFolderName(raw)
);



// Stage 11 exact-id safety guard
const __stage11Pick = (...values) => {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
    if (typeof value === 'boolean') return value;
  }
  return '';
};
const __stage11Source = source || {};
const __stage11Args = args || __stage11Source.args || __stage11Source.payload?.args || {};
const __stage11Payload = typeof payload !== 'undefined' ? payload : (__stage11Source.payload || {});
const __stage11IdFields = ["folderId", "targetId", "fileId"];
const __stage11AlsoFields = [];
const __stage11HasId = Boolean(__stage11Pick(...__stage11IdFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11HasAlso = __stage11AlsoFields.length === 0 || Boolean(__stage11Pick(...__stage11AlsoFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11Allowed = __stage11HasId && __stage11HasAlso;
const __stage11Response = __stage11Allowed ? '' : "Mia chưa xoá folder vì hành động này cần folderId cụ thể. Bạn hãy tìm folder trước, kiểm tra đúng folder, rồi gửi lại kèm folderId nhé.";

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),

    folderId,
    targetId: folderId,
    folderName,
    targetName: folderName,

    hasTarget: Boolean(__stage11Allowed && (folderId || folderName)),

    response: __stage11Response ? __stage11Response : folderId || folderName
      ? ''
      : '🗑️ <b>Xóa folder</b>\n\nVí dụ:\n<code>xóa folder test_n8n</code>',
  },
}];

const source = $('Prepare Action').item.json || {};
const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      targetId: '',
      response: 'Không tìm thấy file/folder phù hợp với: <i>' + String(source.targetName || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</i>'
    }
  }];
}

const target = rows[0];

return [{
  json: {
    ...source,
    ...target,
    targetId: target.id || source.targetId || source.folderId || source.fileId || '',
    targetName: target.name || source.targetName || source.folderName || source.fileName || '',
    webViewLink: target.webViewLink || source.webViewLink || '',
    mimeType: target.mimeType || source.mimeType || ''
  }
}];

const source = $('Prepare Action').item.json || {};
const current = $input.item.json || {};

const targetId =
  current.targetId ||
  current.folderId ||
  current.fileId ||
  current.id ||
  source.targetId ||
  source.folderId ||
  source.fileId ||
  '';

if (!targetId) {
  return [{
    json: {
      ...source,
      response: 'Không tìm thấy ID file/folder để đưa vào thùng rác.'
    }
  }];
}

return [{
  json: {
    ...source,
    ...current,
    targetId,
    targetName: current.name || current.targetName || source.targetName || source.folderName || source.fileName || ''
  }
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};

const name = item.name || item.targetName || source.targetName || source.folderName || source.fileName || 'Không rõ tên';
const id = item.id || item.targetId || source.targetId || source.folderId || source.fileId || '';
const link = item.webViewLink || source.webViewLink || '';
const isFolder = item.mimeType === 'application/vnd.google-apps.folder' || source.mode === 'folder';
const trashed = item.trashed === true;

let text = trashed
  ? '🗑️ <b>Đã đưa ' + (isFolder ? 'folder' : 'file') + ' vào thùng rác</b>\n\n'
  : '⚠️ <b>Chưa xác nhận được đã vào thùng rác</b>\n\n';

text += (isFolder ? '📁 ' : '📄 ') + '<b>' + escapeHtml(name) + '</b>\n';

if (id) {
  text += 'ID: <code>' + escapeHtml(id) + '</code>\n';
}

if (link) {
  text += '🔗 <a href="' + escapeHtml(link) + '">Mở trong Drive</a>\n';
}

if (!trashed) {
  text += '\nOutput không có <code>trashed: true</code>. Hãy kiểm tra lại credential hoặc node trash.';
}

return [{
  json: {
    chatId: source.chatId || item.chatId,
    text: text.trim()
  }
}];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
